cypress_script:
describe('Tool Tips Page', () => {
  it('should display tooltip on hover over the button', () => {
    cy.visit('https://demoqa.com/tool-tips');
    cy.get('#toolTipButton').trigger('mouseover');
    cy.get('.tooltip-inner').should('be.visible');
  });

  it('should not display tooltip when not hovering', () => {
    cy.visit('https://demoqa.com/tool-tips');
    cy.get('#toolTipButton').should('be.visible');
    cy.get('.tooltip-inner').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Tool Tips Page', () => {
  test('should display tooltip on hover over the button', async ({ page }) => {
    await page.goto('https://demoqa.com/tool-tips');
    const button = page.locator('#toolTipButton');
    await button.hover();
    const tooltip = page.locator('.tooltip-inner');
    await expect(tooltip).toBeVisible();
  });

  test('should not display tooltip when not hovering', async ({ page }) => {
    await page.goto('https://demoqa.com/tool-tips');
    const button = page.locator('#toolTipButton');
    await expect(button).toBeVisible();
    const tooltip = page.locator('.tooltip-inner');
    await expect(tooltip).not.toBeVisible();
  });
});
